package bookstore

import "sort"

// groupCosts[i] is the price, in cents, of a group of i distinct books.
var groupCosts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the price, in cents, of the basket with the biggest possible
// discount applied. Each book is identified by an integer from 1 to 5.
func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}

	// Greedily form groups, always taking one copy of each of the most
	// in-demand titles.
	var groups []int
	for {
		distinct := 0
		for _, c := range counts {
			if c > 0 {
				distinct++
			}
		}
		if distinct == 0 {
			break
		}
		sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
		for i := 0; i < distinct; i++ {
			counts[i]--
		}
		groups = append(groups, distinct)
	}

	// A group of five plus a group of three costs 5160, while two groups of
	// four cost 5120, so convert every such pair of groups.
	fives, threes := 0, 0
	for _, size := range groups {
		switch size {
		case 5:
			fives++
		case 3:
			threes++
		}
	}
	for i := 0; i < fives && i < threes; i++ {
		groups[i] = 4
	}

	cost := 0
	for _, size := range groups {
		cost += groupCosts[size]
	}
	return cost
